#!/usr/bin/env bash
# Upload the JKS/PKCS12 keystores generated by 01-generate-ca-and-certs.sh as
# K8s secrets consumed by CFK and client apps.
#
# Secrets created (per region):
#   kafka-tls         — truststore + per-broker keystores (kafka-0..14.p12)
#                       CFK auto-mounts this at /mnt/sslcerts/ on each broker pod
#                       and the broker uses pkcs12 at keystore.p12 / truststore.p12
#   kraft-tls         — truststore + per-controller keystores (kraft-0..2.p12)
#   client-tls-producer, client-tls-consumer, client-tls-admin — per-role keystores
#                       (mount these into producer/consumer deployments)

set -euo pipefail

# Load .env for cluster-specific values
REPO_ROOT=$(cd "$(dirname "$0")/.." && pwd)
[[ -f "$REPO_ROOT/.env" ]] && source "$REPO_ROOT/.env"

# Optional first arg: east1 | east2 | both (default: both)
TARGET="${1:-both}"

: "${CERTS_DIR:=/tmp/mtls-certs}"
CTX_EAST1="${KUBECTL_CONTEXT_REGION1:-<your-east1-context>}"
CTX_EAST2="${KUBECTL_CONTEXT_REGION2:-<your-east2-context>}"
NS_EAST1="${NAMESPACE_REGION1:-cflt-east1}"
NS_EAST2="${NAMESPACE_REGION2:-cflt-east2}"

if [[ ! -f "$CERTS_DIR/truststore.p12" || ! -f "$CERTS_DIR/jksPassword.txt" ]]; then
  echo "ERROR: $CERTS_DIR/truststore.p12 or jksPassword.txt missing. Run 01-generate-ca-and-certs.sh first."
  exit 1
fi

PASS=$(cat "$CERTS_DIR/jksPassword.txt")

create_kafka_secret() {
  local ctx=$1 ns=$2 region=$3    # region=east1 or east2
  echo "─── $region ($ns): kafka-tls secret ───"
  # Pull together: truststore + per-broker keystores for THIS region
  # CFK convention: keystore.p12 is used by broker-0 directly;
  # for per-broker certs, mount at keystore.p12 and CFK uses it as-is.
  # Since all brokers share a wildcard cert in simple deployments, we take the
  # per-broker-0 keystore as the common one (CN wildcarded over brokers via SANs).
  # Alternative pattern (more secure): per-pod secrets via statefulset volumeClaimTemplate.

  # We'll build a secret with:
  #   truststore.p12            — the one truststore
  #   keystore.p12              — kafka-${region}-0.p12 (or build a shared keystore)
  #   jksPassword.txt           — password file
  # Plus per-broker-N keystore files under predictable names for CFK to pick up.

  local tmp=$(mktemp -d)
  cp "$CERTS_DIR/truststore.p12" "$tmp/truststore.p12"
  cp "$CERTS_DIR/jksPassword.txt" "$tmp/jksPassword.txt"
  # Shared keystore (simplest working option): use broker-0's cert on all brokers.
  # SANs include DNS:kafka which covers all brokers' internal hostnames.
  cp "$CERTS_DIR/kafka-${region}-0.p12" "$tmp/keystore.p12"

  kubectl --context "$ctx" -n "$ns" delete secret kafka-tls --ignore-not-found >/dev/null
  kubectl --context "$ctx" -n "$ns" create secret generic kafka-tls \
    --from-file="truststore.p12=$tmp/truststore.p12" \
    --from-file="keystore.p12=$tmp/keystore.p12" \
    --from-file="jksPassword.txt=$tmp/jksPassword.txt"
  rm -rf "$tmp"
  echo "  ✓ created secret/kafka-tls in $ns"
}

create_kraft_secret() {
  local ctx=$1 ns=$2 region=$3
  echo "─── $region ($ns): kraft-tls secret ───"
  local tmp=$(mktemp -d)
  cp "$CERTS_DIR/truststore.p12" "$tmp/truststore.p12"
  cp "$CERTS_DIR/jksPassword.txt" "$tmp/jksPassword.txt"
  cp "$CERTS_DIR/kraft-${region}-0.p12" "$tmp/keystore.p12"
  kubectl --context "$ctx" -n "$ns" delete secret kraft-tls --ignore-not-found >/dev/null
  kubectl --context "$ctx" -n "$ns" create secret generic kraft-tls \
    --from-file="truststore.p12=$tmp/truststore.p12" \
    --from-file="keystore.p12=$tmp/keystore.p12" \
    --from-file="jksPassword.txt=$tmp/jksPassword.txt"
  rm -rf "$tmp"
  echo "  ✓ created secret/kraft-tls in $ns"
}

create_client_secrets() {
  local ctx=$1 ns=$2
  for role in producer consumer admin; do
    echo "─── $ns: client-tls-$role secret ───"
    local tmp=$(mktemp -d)
    cp "$CERTS_DIR/truststore.p12" "$tmp/truststore.p12"
    cp "$CERTS_DIR/jksPassword.txt" "$tmp/jksPassword.txt"
    cp "$CERTS_DIR/client-$role.p12" "$tmp/keystore.p12"
    kubectl --context "$ctx" -n "$ns" delete secret "client-tls-$role" --ignore-not-found >/dev/null
    kubectl --context "$ctx" -n "$ns" create secret generic "client-tls-$role" \
      --from-file="truststore.p12=$tmp/truststore.p12" \
      --from-file="keystore.p12=$tmp/keystore.p12" \
      --from-file="jksPassword.txt=$tmp/jksPassword.txt"
    rm -rf "$tmp"
    echo "  ✓ created secret/client-tls-$role in $ns"
  done
}

if [[ "$TARGET" == "east1" || "$TARGET" == "both" ]]; then
  create_kafka_secret "$CTX_EAST1" "$NS_EAST1" east1
  create_kraft_secret "$CTX_EAST1" "$NS_EAST1" east1
  create_client_secrets "$CTX_EAST1" "$NS_EAST1"
fi

if [[ "$TARGET" == "east2" || "$TARGET" == "both" ]]; then
  create_kafka_secret "$CTX_EAST2" "$NS_EAST2" east2
  create_kraft_secret "$CTX_EAST2" "$NS_EAST2" east2
  create_client_secrets "$CTX_EAST2" "$NS_EAST2"
fi

echo
echo "Done. Secrets ready. Next: deploy CP via 'make deploy-cp-east{1,2}'."
